def create_dragonfly_connection(decode_responses=True):
    if not DRAGONFLY_PASSWORD:
        logger.warning("DRAGONFLY_PASSWORD not set, Dragonfly disabled")
        return None
    try:
        logger.info(f"Connecting to Dragonfly at {DRAGONFLY_URL}:{DRAGONFLY_PORT}")
        client = redis.Redis(
            host=DRAGONFLY_URL,
            port=DRAGONFLY_PORT,
            password=DRAGONFLY_PASSWORD,
            ssl=True,
            ssl_cert_reqs='none',
            decode_responses=decode_responses,
            socket_timeout=10,
            socket_connect_timeout=10,
            health_check_interval=30
        )
        client.ping()
        logger.info(f"Dragonfly connected successfully: {DRAGONFLY_URL}:{DRAGONFLY_PORT}")
        return client
    except Exception as e:
        logger.error(f"Dragonfly connection failed: {e}")
        return None
