class DragonflyStorage:
    CONV_PREFIX = "tiffytime:conv:"
    RESEARCH_PREFIX = "tiffytime:research:"
    USER_CONVS_PREFIX = "tiffytime:user_convs:"
    USER_RESEARCH_PREFIX = "tiffytime:user_research:"
    TTL_SECONDS = 365 * 24 * 60 * 60
    @staticmethod
    def _get_client():
        global dragonfly_client
        if dragonfly_client is None:
            dragonfly_client = create_dragonfly_connection()
        return dragonfly_client
    @classmethod
    def save_conversation(cls, conv_id: str, conv_ dict) -> bool:
        client = cls._get_client()
        if not client:
            return False
        try:
            key = f"{cls.CONV_PREFIX}{conv_id}"
            client.setex(key, cls.TTL_SECONDS, json.dumps(conv_data))
            user_id = conv_data.get('user_id')
            if user_id:
                user_key = f"{cls.USER_CONVS_PREFIX}{user_id}"
                client.sadd(user_key, conv_id)
                client.expire(user_key, cls.TTL_SECONDS)
            return True
        except Exception as e:
            logger.error(f"Dragonfly save_conversation error: {e}")
            return False
    @classmethod
    def get_conversation(cls, conv_id: str) -> Optional[dict]:
        client = cls._get_client()
        if not client:
            return None
        try:
            key = f"{cls.CONV_PREFIX}{conv_id}"
            data = client.get(key)
            if 
                if isinstance(data, bytes):
                    data = data.decode('utf-8')
                elif not isinstance(data, str):
                    data = str(data)
                return json.loads(data)
            return None
        except Exception as e:
            logger.error(f"Dragonfly get_conversation error: {e}")
            return None
    @classmethod
    def delete_conversation(cls, conv_id: str, user_id: str) -> bool:
        client = cls._get_client()
        if not client:
            return False
        try:
            key = f"{cls.CONV_PREFIX}{conv_id}"
            client.delete(key)
            user_key = f"{cls.USER_CONVS_PREFIX}{user_id}"
            client.srem(user_key, conv_id)
            return True
        except Exception as e:
            logger.error(f"Dragonfly delete_conversation error: {e}")
            return False
    @classmethod
    def get_user_conversations(cls, user_id: str) -> List[dict]:
        client = cls._get_client()
        if not client:
            return []
        try:
            user_key = f"{cls.USER_CONVS_PREFIX}{user_id}"
            conv_ids_set = client.smembers(user_key)
            conv_ids = list(conv_ids_set) if conv_ids_set else []
            conversations = []
            for conv_id in conv_ids:
                if isinstance(conv_id, bytes):
                    conv_id = conv_id.decode('utf-8')
                conv = cls.get_conversation(conv_id)
                if conv:
                    conversations.append(conv)
            return conversations
        except Exception as e:
            logger.error(f"Dragonfly get_user_conversations error: {e}")
            return []
