    @classmethod
    def get_user_research_sessions(cls, user_id: str) -> List[dict]:
        client = cls._get_client()
        if not client:
            return []
        try:
            user_key = f"{cls.USER_RESEARCH_PREFIX}{user_id}"
            session_ids_raw = client.smembers(user_key)
            session_ids: List[str] = []
            if session_ids_raw:
                for sid in session_ids_raw:
                    if isinstance(sid, bytes):
