def parse_dragonfly_url(url_raw: str, port_raw: str) -> tuple:
    from urllib.parse import urlparse
    url = url_raw.strip()
    if '://' in url:
        parsed = urlparse(url)
        host = parsed.hostname or url
        port = parsed.port or int(port_raw)
    else:
        if ':' in url:
            parts = url.rsplit(':', 1)
            host = parts[0]
            try:
                port = int(parts[1])
            except ValueError:
                host = url
                port = int(port_raw)
        else:
            host = url
            port = int(port_raw)
    return host, port
