    @classmethod
    def get_relevant_context(cls, user_id: str, query: str, 
                              max_results: int = 5) -> str:
        memories = cls.search_memories(
            query=query,
            limit=max_results,
            container_tags=[f"user_{user_id}"],
            rerank=True
        )
        if not memories:
            return ""
        context_parts = ["=== KORÁBBI RELEVÁNS INFORMÁCIÓK ==="]
        for i, mem in enumerate(memories[:max_results], 1):
            chunks = mem.get('chunks', [])
            if chunks:
                relevant_text = chunks[0].get('content', '')[:500]
            else:
                relevant_text = mem.get('content', '')[:500] if mem.get('content') else ''
            if relevant_text:
                context_parts.append(f"\n[{i}] {relevant_text}")
        context_parts.append("\n=== KONTEXTUS VÉGE ===\n")
        return "\n".join(context_parts)
