    completed_sessions = len([s for s in user_sessions if s.status == TaskStatus.COMPLETED])
    total_sources = sum(s.total_sources_found for s in user_sessions)
    topics = [s.goal[:50] for s in user_sessions]
    topic_frequency = {}
    for topic in topics:
        words = topic.lower().split()
        for word in words:
            if len(word) > 4:
                topic_frequency[word] = topic_frequency.get(word, 0) + 1
    top_topics = sorted(topic_frequency.items(), key=lambda x: x[1], reverse=True)[:10]
    user_agents = [a for a in AUTONOMOUS_AGENTS.values() if a.get('user_id') == user_id]
    user_alerts = [a for a in RESEARCH_ALERTS.values() if a.user_id == user_id]
    user_graphs = [g for g in KNOWLEDGE_GRAPHS.values() if g.user_id == user_id]
    return {
        "user_id": user_id,
        "total_research_sessions": total_sessions,
        "completed_sessions": completed_sessions,
        "completion_rate": (completed_sessions / total_sessions * 100) if total_sessions > 0 else 0,
        "total_sources_analyzed": total_sources,
        "average_sources_per_session": total_sources / total_sessions if total_sessions > 0 else 0,
        "top_research_topics": [{"topic": t[0], "count": t[1]} for t in top_topics],
        "active_autonomous_agents": len([a for a in user_agents if a.get('status') == 'active']),
        "active_research_alerts": len([a for a in user_alerts if a.active]),
        "knowledge_graphs_created": len(user_graphs),
        "generated_at": datetime.now().isoformat()
    }
